/**
 * The class description: the ontology (messages.lml) as data.
 * Generated by service-publications-docs scripts/generate_class_description.rb
 * into class-description.generated.json; never edited by hand.
 */
import raw from "./class-description.generated.json";

export type Primitive = "String" | "Integer" | "Boolean" | "Date" | "Float" | "Time" | "Hash" | "HashOrText" | "DateOrText";

export interface AttributeDescription {
  /** Ontology attribute name (the form field id). */
  name: string;
  /** Key in the stored YAML (differs from name only for declared yaml mappings). */
  wire: string;
  type: string;
  kind: "primitive" | "class" | "enum";
  required: boolean;
  collection: boolean;
  default?: string;
}

export interface ClassDescription {
  attributes: AttributeDescription[];
}

export interface Description {
  source: string;
  primitives: Primitive[];
  enums: Record<string, string[]>;
  classes: Record<string, ClassDescription>;
}

export const description = raw as unknown as Description;
